import { readFile, readdir } from "node:fs/promises";
import path from "node:path";

/**
 * Run 115 S3b (R6/R5): entry discovery for the first-party `@role-model-router/foldkit` wrapper.
 *
 * The vendored Foldkit package is source-only: its published manifest maps every subpath to
 * `./dist/*.js`, and `dist/` is deliberately absent from the vendoring payload. This module
 * therefore derives the esbuild entry list from the vendored `package.json` exports map
 * (never hand-typed) and resolves each published target back to the `src/*.ts` file it was
 * compiled from. A mapped source file that does not exist must fail the build loudly: silently
 * dropping a published subpath would produce a wrapper that lies about its surface.
 */
const here = import.meta.dirname;
const repoRoot = path.resolve(here, "..", "..", "..");

export const vendoredPackageDir = path.join(repoRoot, "vendor", "foldkit", "packages", "foldkit");

/** The public exports map of the vendored package - the source of truth for entry discovery. */
export async function readPublishedExports(packageDir = vendoredPackageDir) {
  const manifestPath = path.join(packageDir, "package.json");
  const manifest = JSON.parse(await readFile(manifestPath, "utf8"));
  if (manifest.exports === undefined || typeof manifest.exports !== "object") {
    throw new Error(`vendored package ${manifestPath} publishes no exports map`);
  }
  return manifest.exports;
}

/**
 * Turn a published target (`./dist/<rel>.js`) into the vendored source file it was compiled
 * from (`src/<rel>.ts`). Anything that is not a `./dist/*.js` import is refused, so a manifest
 * shape this wrapper does not understand fails instead of guessing.
 */
export function sourceRelativePath(target, subpath) {
  const specifier = typeof target === "string" ? target : (target?.import ?? target?.default);
  if (
    typeof specifier !== "string" ||
    !specifier.startsWith("./dist/") ||
    !specifier.endsWith(".js")
  ) {
    throw new Error(
      `published export "${subpath}" does not resolve to a ./dist/*.js import: ${JSON.stringify(target)}`,
    );
  }
  return `src/${specifier.slice("./dist/".length, -".js".length)}.ts`;
}

/**
 * Exact-name existence check. `readdir` never folds case, so a source file whose spelling
 * differs from the manifest (`devTools` vs `devtools`) is reported as missing instead of being
 * opened through a case-insensitive filesystem.
 */
async function exactFile(file) {
  try {
    for (const entry of await readdir(path.dirname(file))) {
      if (entry === path.basename(file)) return file;
    }
  } catch {
    // A missing parent directory means the candidate cannot exist either.
  }

import { Option, String } from 'effect'

import { OptionExt, StringExt } from '../effectExtensions/index.js'
import { UrlRequest } from '../navigation/urlRequest.js'
import { Url } from '../url/index.js'

/** Configuration for URL routing with handlers for URL requests and URL changes. */
export type RoutingConfig<Message> = Readonly<{
  onUrlRequest: (request: UrlRequest) => Message
  onUrlChange: (url: Url) => Message
}>

export const addNavigationEventListeners = <Message>(
  dispatch: (message: Message) => void,
  routingConfig: RoutingConfig<Message>,
): (() => void) => {
  const removePopStateListener = addPopStateListener(dispatch, routingConfig)
  const removeLinkClickListener = addLinkClickListener(dispatch, routingConfig)
  const removeProgrammaticNavigationListener =
    addProgrammaticNavigationListener(dispatch, routingConfig)

  return () => {
    removePopStateListener()
    removeLinkClickListener()
    removeProgrammaticNavigationListener()
  }
}

const addPopStateListener = <Message>(
  dispatch: (message: Message) => void,
  routingConfig: RoutingConfig<Message>,
): (() => void) => {
  const onPopState = () => {
    dispatch(routingConfig.onUrlChange(locationToUrl()))
  }

  window.addEventListener('popstate', onPopState)
  return () => {
    window.removeEventListener('popstate', onPopState)
  }
}

export const addLinkClickListener = <Message>(
  dispatch: (message: Message) => void,
  routingConfig: RoutingConfig<Message>,
): (() => void) => {
  const onLinkClick = (event: MouseEvent) => {
    const isNonPrimaryButton = event.button !== 0
    const isModifierKeyPressed =
      event.metaKey || event.ctrlKey || event.shiftKey || event.altKey
    const isDefaultPrevented = event.defaultPrevented

    if (isNonPrimaryButton || isModifierKeyPressed || isDefaultPrevented) {
      return
    }

    const eventTarget = event.target
    if (!(eventTarget instanceof Element)) {
      return
    }

    const maybeLink = Option.fromNullishOr(eventTarget.closest('a'))
    if (Option.isNone(maybeLink)) {
      return
    }

    const { value: link } = maybeLink
    const { href } = link
    if (String.isEmpty(href)) {
      return
    }

    const isNonSelfTarget =
      !String.isEmpty(link.target) && link.target !== '_self'
    const isDownloadLink = link.hasAttribute('download')

    if (isNonSelfTarget || isDownloadLink) {
      return
    }

    event.preventDefault()

    const linkUrl = new URL(href)
    const currentUrl = new URL(window.location.href)

    if (linkUrl.origin !== currentUrl.origin) {
      dispatch(routingConfig.onUrlRequest(UrlRequest.External({ href })))
      return
    }

    dispatch(
      routingConfig.onUrlRequest(
        UrlRequest.Internal({ url: urlToFoldkitUrl(linkUrl) }),
      ),
    )
  }

  document.addEventListener('click', onLinkClick)
  return () => {
    document.removeEventListener('click', onLinkClick)
  }
}

const addProgrammaticNavigationListener = <Message>(
  dispatch: (message: Message) => void,
  routingConfig: RoutingConfig<Message>,
): (() => void) => {
  const onProgrammaticNavigation = () => {
    dispatch(routingConfig.onUrlChange(locationToUrl()))
  }

  window.addEventListener('foldkit:urlchange', onProgrammaticNavigation)
  return () => {
    window.removeEventListener('foldkit:urlchange', onProgrammaticNavigation)
  }
}

const urlToFoldkitUrl = (url: URL): Url => {
  const { protocol, hostname, port, pathname, search, hash } = url

  return {
    protocol,
    host: hostname,
    port: OptionExt.fromString(port),
    pathname,
    search: StringExt.stripPrefixNonEmpty('?')(search),
    hash: StringExt.stripPrefixNonEmpty('#')(hash),
  }
}

